@ccclass('ItemTabDailyTask')
export class ItemTabDailyTask extends Component {
    @property({type:Enum(DAILYTASK_TYPE)})
    tabType:DAILYTASK_TYPE = DAILYTASK_TYPE.LOGIN;

    @property(Button)
    btnTab:Button;

    @property(Sprite)
    bg:Sprite;

    @property(SpriteFrame)
    sfON:SpriteFrame;

    @property(SpriteFrame)
    sfOFF:SpriteFrame;

    @property(Node)
    nodeActive:Node = null;

    @property(Node)
    nodeDeactive:Node = null;

    protected onEnable(): void {
        this.btnTab.node.on(Constants.CLICK,this.touchTab,this);
        clientEvent.on(Constants.TABDAILYTASK_UPDATE,this.showTab,this);
    }

    protected onDisable(): void {
        this.btnTab.node.off(Constants.CLICK,this.touchTab,this);
        clientEvent.off(Constants.TABDAILYTASK_UPDATE,this.showTab,this);
    }

    setItemON(){
        this.bg.spriteFrame = this.sfON;
        this.nodeActive.active = true;
        this.nodeDeactive.active = false;
    }

    setItemOff(){
        this.bg.spriteFrame = this.sfOFF;
        this.nodeActive.active = false;
        this.nodeDeactive.active = true;
    }

    touchTab(){
        clientEvent.dispatchEvent(Constants.TOUCH_TABDAILYTASK,this.tabType);
    }

    showTab(currTab:DAILYTASK_TYPE){
        // console.log("showTab:"+this.tabType,currTab);
        if(this.tabType == currTab){
            this.setItemON();
        }else{
            this.setItemOff();
        }
    }
}

